create table public.audit_logs (id bigint generated by default as identity primary key,business_id bigint references public.businesses(id) on delete set null,actor_user_id uuid references public.app_users(id) on delete set null,action text not null,model_type text,model_id bigint,description text,old_values jsonb,new_values jsonb,ip_address inet,user_agent text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.audit_logs enable row level security;
revoke all on table public.audit_logs from anon,authenticated;
grant select,insert on table public.audit_logs to authenticated;
create index audit_logs_business_created_idx on public.audit_logs(business_id,created_at);
create index audit_logs_model_idx on public.audit_logs(model_type,model_id);
create index audit_logs_actor_created_idx on public.audit_logs(actor_user_id,created_at);
create policy audit_logs_read on public.audit_logs for select to authenticated using (business_id is null or business_id=(select private.current_business_id()));
create policy audit_logs_insert on public.audit_logs for insert to authenticated with check (business_id is null or business_id=(select private.current_business_id()));
create or replace function private.audit_log_immutable() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if tg_op <> 'INSERT' then raise exception 'audit_logs is append-only'; end if; return new; end $$;
revoke all on function private.audit_log_immutable() from public,anon,authenticated;
create trigger audit_logs_immutable before update or delete on public.audit_logs for each row execute function private.audit_log_immutable();